{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-04",
  "sketch": {
    "components": ["Mobile app", "POST /premium/unlock endpoint", "Entitlement/premium service", "Account record"],
    "dataStores": ["Account entitlement store"],
    "externalServices": ["App Store / Play Store in-app purchase receipts"],
    "trustBoundaries": ["Mobile client to backend API", "Backend to app store receipt validation"],
    "dataClasses": ["payment"],
    "exposure": "public",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "ElevationOfPrivilege",
      "title": "Client decides it paid: sending purchased=true unlocks premium for free",
      "scenario": "Anyone who can craft an HTTP request (proxy on a jailbroken phone, curl, repackaged APK) calls POST /premium/unlock with {\"purchased\": true} and no real purchase. The server makes the entitlement decision from a client-controlled field, so the attacker gets paid features for free. Published in a forum this scales to every user of the app and directly removes purchase revenue.",
      "component": "POST /premium/unlock endpoint",
      "likelihood": 5,
      "impact": 4,
      "evidence": [
        { "quote": "The server trusts the client flag \"purchased\": true and unlocks premium for the account." }
      ],
      "asvs": [],
      "cwe": ["CWE-602", "CWE-807"],
      "plainLanguage": "The phone tells the server 'I paid' and the server believes it, so anyone can turn on premium without paying.",
      "requirement": {
        "title": "Grant premium only from a server-verified purchase, never a client flag",
        "given": "a client calls POST /premium/unlock",
        "when": "the request body contains a purchased flag or any other client-asserted entitlement field",
        "then": "the server ignores that field and grants premium only after it has itself verified the purchase with the store"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Forged or self-signed receipts accepted because the store never validates them",
      "scenario": "The design sends a receipt but states no server-to-server validation with Apple or Google. An attacker submits a fabricated or modified receipt blob (or one from a sandbox/test purchase) to POST /premium/unlock. Without checking the store's signature, bundle id and environment, the backend cannot tell a real purchase from a fake one and unlocks premium.",
      "component": "Receipt handling in /premium/unlock",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "When a purchase succeeds the app calls POST /premium/unlock with the receipt." }
      ],
      "asvs": [],
      "cwe": ["CWE-345"],
      "plainLanguage": "Nobody checks the receipt with Apple or Google, so a made-up receipt works just as well as a real one.",
      "requirement": {
        "title": "Verify every receipt with the store before granting entitlement",
        "given": "a receipt is submitted to /premium/unlock",
        "when": "the backend processes it",
        "then": "it calls the Apple/Google verification API server-to-server and rejects the request unless the signature, bundle/package id, product id and production environment all match"
      }
    },
    {
      "stride": "Tampering",
      "title": "One real receipt replayed to unlock premium on unlimited accounts",
      "scenario": "An attacker makes a single legitimate purchase, captures the receipt from the request, and replays it to POST /premium/unlock from many accounts, or sells it. Because nothing in the design binds a transaction id to exactly one account or marks it consumed, each replay grants another premium entitlement from one payment.",
      "component": "Entitlement grant logic",
      "likelihood": 4,
      "impact": 4,
      "evidence": [
        { "quote": "When a purchase succeeds the app calls POST /premium/unlock with the receipt." }
      ],
      "asvs": [],
      "cwe": ["CWE-294"],
      "plainLanguage": "Buy once, copy the receipt, and reuse it on as many accounts as you like.",
      "requirement": {
        "title": "Bind each store transaction to one account and consume it",
        "given": "a verified receipt containing a store transaction id",
        "when": "that transaction id has already been recorded against any account",
        "then": "the unlock is rejected and the duplicate attempt is recorded, so each transaction can grant entitlement exactly once"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Unlock premium on someone else's account by changing the account in the request",
      "scenario": "The design says premium is unlocked 'for the account' but shows no authenticated session or check that the caller owns that account. An attacker who can supply or alter an account identifier can unlock (or, with a crafted payload, downgrade) other people's accounts, and can gift premium to arbitrary users.",
      "component": "Account resolution in /premium/unlock",
      "likelihood": 3,
      "impact": 3,
      "evidence": [
        { "quote": "The server trusts the client flag \"purchased\": true and unlocks premium for the account." }
      ],
      "asvs": ["V8.2.1"],
      "cwe": ["CWE-639"],
      "plainLanguage": "The request can name which account gets premium, so you could switch on premium for an account that isn't yours.",
      "requirement": {
        "title": "Derive the target account from the authenticated session",
        "given": "an authenticated user calls /premium/unlock",
        "when": "the request includes an account or user identifier",
        "then": "the server ignores it and applies the entitlement only to the account in the verified session, returning 403 for any mismatch"
      }
    },
    {
      "stride": "Repudiation",
      "title": "Refunded and cancelled purchases keep premium, with no record to prove the grant",
      "scenario": "Premium is switched on at purchase time and the design describes no store notification handling or record of why an account is premium. A user buys, uses premium, then requests a refund or cancels the subscription and keeps the features; finance cannot reconcile entitlements against actual payments and support cannot show who granted premium or on which transaction.",
      "component": "Entitlement lifecycle",
      "likelihood": 4,
      "impact": 3,
      "evidence": [
        { "quote": "In-app purchases unlock premium" },
        { "quote": "unlocks premium for the account" }
      ],
      "asvs": [],
      "cwe": ["CWE-778"],
      "plainLanguage": "Buy, get a refund, keep premium, and nobody can prove what happened.",
      "requirement": {
        "title": "Track entitlement state against the store and revoke on refund",
        "given": "an account has premium granted from a store transaction",
        "when": "the store sends a refund, chargeback, cancellation or expiry notification for that transaction",
        "then": "the entitlement is revoked and the change is stored with the transaction id, timestamp and reason"
      }
    }
  ]
}
